```go
package main

import (
    "fmt"
    "strconv"
)

func parsePort(text string) (uint16, error) {
    value, err := strconv.ParseUint(text, 10, 16)
    if err != nil {
        return 0, fmt.Errorf("port %q: %w", text, err)
    }
    if value == 0 {
        return 0, fmt.Errorf("port must be positive")
    }
    return uint16(value), nil
}

func main() {
    port, err := parsePort("8080")
    fmt.Println(port, err)
}
```
The output is `8080 <nil>`. Syntax and uint16 range are checked by strconv; the function separately enforces a positive domain value.

