    "fmt"
    "strconv"
)

func main() {
    fmt.Println(strconv.Itoa(65))
    fmt.Println(strconv.FormatInt(65, 2))
    fmt.Println(string(rune(65)))
}
```
The outputs are `65`, `1000001`, and `A`. Each operation states a different representation explicitly.

```go
package main

import (
    "fmt"
    "math"
    "strconv"
)

func parsePercent(text string) (float64, error) {
    value, err := strconv.ParseFloat(text, 64)
    if err != nil {
        return 0, err
    }
    if math.IsNaN(value) || math.IsInf(value, 0) || value < 0 || value > 100 {
        return 0, fmt.Errorf("percentage must be finite and between 0 and 100")
    }
    return value, nil
}

func main() {
    value, err := parsePercent("87.5")
    fmt.Println(value, err)
}
```
The output is `87.5 <nil>`. NaN, infinity, and out-of-range finite values are rejected by the domain layer.
